# -*- coding: utf-8 -*-
import json, os
BASE = "/home/hatch/workspace/divination/benchmark/phase3/runs/round88/predictions"
os.makedirs(BASE, exist_ok=True)
TRIG = {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
def W(cid, pred, basis, conf):
    obj = {"case_id": cid, "prediction_text": pred, "basis": basis, "confidence": conf, "trigger": dict(TRIG)}
    p = os.path.join(BASE, cid + ".json")
    with open(p, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    with open(p, encoding="utf-8") as f:
        d = json.load(f)
    assert d["case_id"] == cid and set(d) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert 0 <= d["confidence"] <= 1
    assert all(isinstance(d["trigger"][k], bool) for k in ("changed_main","reserve_used","disputed"))
    return os.path.getsize(p)
